  assert.equal(result[1].rate, 9);
});

test('vatSummary sorts by rate from high to low', () => {
  const invoice1 = issueInvoice(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-07',
      lines: [{ sku: 'PRINT-A4', qty: 10 }], // 9% VAT
    }).value,
    []
  ).value;

  const invoice2 = issueInvoice(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-08',
      lines: [{ sku: 'STICKER', qty: 100 }], // 21% VAT
    }).value,
    ['INV-2026-0001']
  ).value;

  const invoice3 = issueInvoice(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-09',
