    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  const issued = issueInvoice(draft, []).value;
  const totals = invoiceTotals(issued);

  const partial = recordPayment(issued, {
    amount: Math.floor(totals.total / 2),
    date: '2026-10-10',
  }).value;

  const draft2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'STICKER', qty: 50 }],
  }).value;

  const issued2 = issueInvoice(draft2, ['INV-2026-0001']).value;
  const totals2 = invoiceTotals(issued2);
  const paid = recordPayment(issued2, {
    amount: totals2.total,
    date: '2026-10-10',
  }).value;

  const result = vatSummary([partial, paid]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // Both invoices contribute to VAT summary regardless of payment status
  assert.equal(result[0].base, 7500);
});

